const raw = $input.item.json;
const content = typeof raw.content === 'string' ? raw.content : JSON.stringify(raw.content);
const msg = JSON.parse(content.trim());
const date = msg.date;
const records = msg.records;

const result = [];
for (const r of records) {
  const dt = new Date(r.time);
  result.push({
    json: {
      date: r.date,
      time: r.time,
      hour: String(dt.getHours()).padStart(2, '0'),
      year: String(dt.getFullYear()),
      month: String(dt.getMonth() + 1).padStart(2, '0'),
      day: String(dt.getDate()).padStart(2, '0'),
      date_partition: `date=${date}`,
      latitude: Number(r.latitude),
      longitude: Number(r.longitude),
      temperature_2m: r.temperature_2m,
      temperature_2m_unit: r.temperature_2m_unit,
      precipitation: r.precipitation,
      precipitation_unit: r.precipitation_unit,
      ozone: r.ozone,
      ozone_unit: r.ozone_unit,
      carbon_dioxide: r.carbon_dioxide,
      carbon_dioxide_unit: r.carbon_dioxide_unit
    }
  });
}

return result;

const items = $input.all().map(i => i.json);
const date = items[0].date;

const longRows = [];
items.forEach(r => {
  [
    {var: 'temperature_2m', unit: r.temperature_2m_unit, ds: 'historical_weather'},
    {var: 'precipitation',  unit: r.precipitation_unit,  ds: 'historical_weather'},
    {var: 'ozone',          unit: r.ozone_unit,          ds: 'air_quality'},
    {var: 'carbon_dioxide', unit: r.carbon_dioxide_unit, ds: 'air_quality'}
  ].forEach(v => {
    longRows.push({
      source: 'open_meteo', dataset: v.ds,
      date: r.date, year: r.year, month: r.month,
      day: r.day, hour: r.hour, time: r.time,
      latitude: r.latitude, longitude: r.longitude,
      variable: v.var, value: r[v.var], unit: v.unit
    });
  });
});

return [{
  json: {
    date,
    rows: longRows,
    path: `processed/environment_observations_long/date=${date}/environment_observations_long_${date}.csv`,
    type: 'processed'
  }
}];

const items = $input.all().map(i => i.json);
const date = items[0].date;

const fields = [
  'date','year','month','day','hour','time','latitude','longitude',
  'temperature_2m','temperature_2m_unit','precipitation','precipitation_unit',
  'ozone','ozone_unit','carbon_dioxide','carbon_dioxide_unit'
];

return [{
  json: {
    date,
